import {expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {resolve} from 'node:path';
import {createHash} from 'node:crypto';
export async function installBatchProbe(page){await page.addInitScript(()=>{const Original=Worker;window.__batch={calls:[],fail:0,hold:0,started:0,stopped:0};window.Worker=class extends Original{constructor(url,options){super(url,options);this.collage=String(url).includes('collage-worker-');if(this.collage)window.__batch.started++;}postMessage(data,...rest){if(this.collage&&data.action==='inspect'&&window.__batch.holdInspect)return;if(this.collage&&data.action==='export'){const probe=window.__batch;probe.calls.push(data.scene.cells.map(c=>c.source_id));if(probe.calls.length===probe.hold)return;if(probe.calls.length===probe.fail){queueMicrotask(()=>this.dispatchEvent(new MessageEvent('message',{data:{id:data.id,error:'Collage processing failed.'}})));return;}}super.postMessage(data,...rest);}terminate(){if(this.collage&&!this.done){this.done=true;window.__batch.stopped++;}super.terminate();}};});}
function inspectZip(path){return JSON.parse(execFileSync(process.env.PHOTO_TEST_PYTHON||resolve('.venv/Scripts/python.exe'),['-c',`import sys,zipfile,json,io
from PIL import Image
with zipfile.ZipFile(sys.argv[1]) as z:
 assert z.testzip() is None
 images=[]
 for name in z.namelist():
  if name.endswith(('.jpg','.png')):
   raw=z.read(name)
   with Image.open(io.BytesIO(raw)) as image:
    image.load();images.append({'name':name,'size':list(image.size),'format':image.format})
 print(json.dumps({'names':z.namelist(),'images':images,'report':json.loads(z.read('report.json')),'book':json.loads(z.read('Collage.pc-collage-batch.json'))}))`,path],{encoding:'utf8'}));}
export async function exerciseCollageBatch(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh;await page.getByRole('button',{name:t('批量拼图','Batch collage'),exact:true}).click();const dialog=page.getByRole('dialog',{name:t('批量拼图','Batch collage'),exact:true}),button=(zh,en)=>dialog.getByRole('button',{name:t(zh,en),exact:true}),field=(zh,en)=>dialog.getByLabel(t(zh,en),{exact:true});
 const bytes=await page.evaluate(async()=>{const c=new OffscreenCanvas(96,64),x=c.getContext('2d'),out=[];for(let i=0;i<13;i++){x.fillStyle=`hsl(${i*27} 60% 40%)`;x.fillRect(0,0,96,64);x.fillStyle='#fff';x.fillRect(4+i*3,8,10,40);out.push([...new Uint8Array(await(await c.convertToBlob()).arrayBuffer())]);}return out;});const files=bytes.map((b,i)=>({name:`Batch-${String(13-i).padStart(2,'0')}.png`,mimeType:'image/png',buffer:Buffer.from(b)}));
 const input=dialog.locator('input[type=file]').first(),project=dialog.locator('input[type=file]').nth(1),download=async(zh,en)=>{const next=page.waitForEvent('download');await button(zh,en).click();return await(await next).path();};
 await input.setInputFiles(files);await expect(dialog.locator('.batch-page')).toHaveCount(4);await expect(button('保存批量清单','Save batch document')).toBeEnabled();
 const original=JSON.parse(readFileSync(await download('保存批量清单','Save batch document'),'utf8'));expect(original.items).toHaveLength(13);for(const item of original.items)expect(item.source.sha256).toBe(createHash('sha256').update(files.find(f=>f.name===item.source.name).buffer).digest('hex'));expect(original.items.every(i=>i.capture_time===null)).toBe(true);
 await field('余图处理','Remainder handling').selectOption('drop');await expect(dialog.locator('.batch-page')).toHaveCount(3);await expect(dialog.locator('.batch-omitted')).toContainText('Batch-01.png');await field('余图处理','Remainder handling').selectOption('merge');await expect(dialog.locator('.batch-page').last().locator('.collage-cells button')).toHaveCount(5);
 await field('每组照片数','Photos per group').selectOption('9');await expect(dialog.locator('.batch-page')).toHaveCount(2);await expect(dialog.locator('.batch-page').last().locator('.collage-cells button')).toHaveCount(4);await field('每组照片数','Photos per group').selectOption('4');await field('余图处理','Remainder handling').selectOption('own');
 await field('分组顺序','Group order').selectOption('filename');await expect(dialog.locator('.collage-cells button').first()).toHaveAttribute('title','Batch-01.png');await field('分组顺序','Group order').selectOption('selection');
 await button('编辑第 1 页','Edit page 1').click();const single=page.getByRole('dialog',{name:t('照片拼图','Photo collage'),exact:true});await expect(single.getByRole('button',{name:t('应用并返回批量','Apply and return to batch'),exact:true})).toBeEnabled();await expect(single.getByRole('button',{name:t('替换照片','Replace photo'),exact:true})).toHaveCount(0);
 await single.getByLabel(t('画布宽度','Canvas width'),{exact:true}).fill('480');await single.getByLabel(t('画布高度','Canvas height'),{exact:true}).fill('320');await single.getByLabel(t('画布高度','Canvas height'),{exact:true}).press('Tab');await single.getByLabel(t('格内缩放','Cell zoom'),{exact:true}).fill('1.4');await single.getByLabel(t('融边精确宽度','Exact blend width'),{exact:true}).fill('32');await single.getByLabel(t('融边精确宽度','Exact blend width'),{exact:true}).press('Tab');await single.getByRole('button',{name:t('应用并返回批量','Apply and return to batch'),exact:true}).click();await dialog.getByRole('button',{name:t('本页样式应用到全部','Apply this style to all'),exact:true}).first().click();
 const cell0=dialog.locator('[data-page="0"][data-batch-cell="0"]'),cell1=dialog.locator('[data-page="1"][data-batch-cell="0"]');
 if(lang==='zh'){await dialog.evaluate(el=>el.scrollTop=0);await cell0.scrollIntoViewIfNeeded();const a=await cell0.boundingBox(),b=await cell1.boundingBox();await page.mouse.move(a.x+a.width/2,a.y+a.height/2);await page.mouse.down();await page.mouse.move(b.x+b.width/2,b.y+b.height/2,{steps:6});await page.mouse.up();}else{await cell0.click();await field('交换目标','Swap target').selectOption('1:0');await button('交换所选照片','Swap selected photos').click();}
 await expect(cell1).toHaveAttribute('title','Batch-13.png');const changed=JSON.parse(readFileSync(await download('保存批量清单','Save batch document'),'utf8'));expect(changed.pages[1].cells[0].zoom).toBe(1.4);expect(changed.pages.every(p=>p.width===480&&p.height===320&&p.edge_blend===32)).toBe(true);
 // A failed atomic import preserves all pages and their identity/framing.
 await input.setInputFiles({name:'Broken.png',mimeType:'image/png',buffer:Buffer.from('broken')});await expect(dialog.getByRole('alert').first()).toBeVisible();await expect(dialog.locator('.batch-page')).toHaveCount(4);await expect(cell1).toHaveAttribute('title','Batch-13.png');
 await project.setInputFiles({name:'Batch.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(changed))});await input.setInputFiles(files.slice(0,2));await expect(dialog.getByRole('alert').first()).toBeVisible();await input.setInputFiles([...files].reverse());await expect(button('保存批量清单','Save batch document')).toBeEnabled();await expect(cell1).toHaveAttribute('title','Batch-13.png');
 await field('批量输出格式','Batch output format').selectOption('jpg');await field('JPEG 质量','JPEG quality').fill('81');await page.evaluate(()=>{window.__batch.fail=2;window.__batch.hold=3;});await button('开始逐页导出','Export pages').click();await expect.poll(()=>page.evaluate(()=>window.__batch.calls.length)).toBe(3);await button('停止处理','Stop processing').click();await expect(button('下载已完成页 ZIP','Download completed pages ZIP')).toBeEnabled();
 const partial=inspectZip(await download('下载已完成页 ZIP','Download completed pages ZIP'));expect(partial.images).toEqual([{name:'Collage-001.jpg',size:[480,320],format:'JPEG'}]);expect(partial.report.pages.map(p=>p.status)).toEqual(['completed','failed','cancelled','pending']);expect(partial.book).toEqual(changed);
 await button('导出未完成页','Export unfinished pages').click();await expect(dialog.locator('.batch-page h3 small').filter({hasText:t('已完成','Completed')})).toHaveCount(4);expect(await page.evaluate(()=>window.__batch.calls.length)).toBe(6);const calls=await page.evaluate(()=>window.__batch.calls);expect(calls[3]).toEqual(calls[1]);expect(calls[4]).toEqual(calls[2]);
 const full=inspectZip(await download('下载已完成页 ZIP','Download completed pages ZIP'));expect(full.images).toHaveLength(4);expect(full.images.every(i=>i.size[0]===480&&i.size[1]===320&&i.format==='JPEG')).toBe(true);expect(full.report.pages.every(p=>p.status==='completed')).toBe(true);expect(full.book).toEqual(changed);expect(full.names.every(n=>!n.startsWith('Batch-'))).toBe(true);
 await expect(dialog.locator('.batch-page img').first()).toBeVisible();await dialog.evaluate(el=>el.scrollTop=0);await expect(dialog.locator('.batch-page').first().locator('img')).toBeVisible();await dialog.screenshot({path:info.outputPath('collage-batch-'+lang+'.png')});expect(await dialog.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true);if(lang==='en')expect(await dialog.innerText()).not.toMatch(/[\u3400-\u9fff]/);await button('关闭','Close').click();await expect(dialog).toHaveCount(0);expect(await page.evaluate(()=>window.__batch.started-window.__batch.stopped)).toBe(0);
 await info.attach('batch-archive-verification',{body:JSON.stringify({partial:partial.report,full:full.report,images:full.images}),contentType:'application/json'});
}

export async function exerciseBatchTransfer(page){
 const files=await page.evaluate(async()=>{const c=new OffscreenCanvas(40,30),x=c.getContext('2d'),out=[];for(let i=0;i<3;i++){x.fillStyle=['red','green','blue'][i];x.fillRect(0,0,40,30);out.push([...new Uint8Array(await(await c.convertToBlob()).arrayBuffer())]);}return out;});const selected=files.map((bytes,i)=>({name:`Transfer-${i}.png`,mimeType:'image/png',buffer:Buffer.from(bytes)}));
 const single=page.getByRole('dialog',{name:'照片拼图',exact:true});await single.locator('input[type=file]').first().setInputFiles(selected);await expect(single.getByRole('button',{name:'批量拼图',exact:true})).toBeEnabled();await single.getByLabel('格内缩放',{exact:true}).fill('1.6');await single.getByLabel('交换照片',{exact:true}).selectOption('2');await single.getByRole('button',{name:'批量拼图',exact:true}).click();const batch=page.getByRole('dialog',{name:'批量拼图',exact:true});await expect(batch.locator('.batch-page')).toHaveCount(1);await expect(batch.locator('.collage-cells button').first()).toHaveAttribute('title','Transfer-2.png');
 const download=page.waitForEvent('download');await batch.getByRole('button',{name:'保存批量清单',exact:true}).click();const document=JSON.parse(readFileSync(await(await download).path(),'utf8'));expect(document.pages[0].cells[2].zoom).toBe(1.6);
 await page.evaluate(()=>window.__batch.holdInspect=true);await batch.locator('input[type=file]').first().setInputFiles(selected[0]);await expect(batch.getByRole('button',{name:'停止处理',exact:true})).toBeVisible();await batch.getByRole('button',{name:'停止处理',exact:true}).click();await expect(batch.getByRole('alert')).toContainText('取消');await expect(batch.locator('.collage-cells button')).toHaveCount(3);await batch.locator('input[type=file]').first().setInputFiles(selected[1]);await expect(batch.getByRole('button',{name:'停止处理',exact:true})).toBeVisible();page.once('dialog',d=>d.accept());await batch.getByRole('button',{name:'关闭',exact:true}).click();await expect(batch).toHaveCount(0);expect(await page.evaluate(()=>window.__batch.started-window.__batch.stopped)).toBe(0);
}
export async function exerciseBatchGallery(page,photos){
 for(const photo of photos)await page.locator('.photo-card').filter({hasText:photo.file_name}).locator('.photo-image').click();await page.locator('.library-toolbar').getByRole('button',{name:'照片拼图',exact:true}).click();const batch=page.getByRole('dialog',{name:'批量拼图',exact:true});await expect(batch.locator('.batch-page')).toHaveCount(4);const next=page.waitForEvent('download');await batch.getByRole('button',{name:'保存批量清单',exact:true}).click();const book=JSON.parse(readFileSync(await(await next).path(),'utf8'));expect(book.items.map(i=>i.source.photo_id).sort()).toEqual(photos.map(p=>p.id).sort());for(const item of book.items)expect(item.source.sha256).toBe(photos.find(p=>p.id===item.source.photo_id).file_hash);await batch.getByRole('button',{name:'关闭',exact:true}).click();await expect(batch).toHaveCount(0);
}
